-- X-REACH Backend - LLM-generated natural-language explanations (SQLite)
--
-- Adds a SECOND explanation pair alongside the existing rule-based
-- patient_explanation / doctor_explanation columns (see limeService.js).
-- These new columns hold a richer, free-text explanation generated by an
-- LLM (Groq, see groqExplanationService.js) from the same LIME contributing
-- factors, phrased for the two different audiences:
--   patient_llm_explanation -- plain-language, patient-friendly wording
--   doctor_llm_explanation  -- clinical terminology, doctor-friendly wording
--
-- Both are nullable: the LLM call is best-effort (network/API-key issues
-- must never block a prediction from being created), so a row may have
-- the original rule-based explanation but no LLM explanation yet.

ALTER TABLE predictions ADD COLUMN patient_llm_explanation TEXT;
ALTER TABLE predictions ADD COLUMN doctor_llm_explanation TEXT;
